node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the order
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%9497%'\").all();
orders.forEach(r => {
  console.log('ORDER:', JSON.stringify(r, null, 2));
  const items = db.prepare('SELECT * FROM order_items WHERE order_id=?').all(r.order_id);
  console.log('ITEMS:', JSON.stringify(items, null, 2));
  const payments = db.prepare('SELECT * FROM order_payments WHERE order_id=?').all(r.order_id);
  console.log('PAYMENTS:', JSON.stringify(payments, null, 2));
});

if (orders.length === 0) {
  console.log('No order found with 9497. Listing all order IDs:');
  const allOrders = db.prepare('SELECT order_id FROM orders LIMIT 20').all();
  allOrders.forEach(r => console.log(r.order_id));
}
"

